  'markdown':
      'import \'dart:async\';\n'
      '\n'
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const MarkdownExample());\n'
      '\n'
      '/// A reply with every block Markdown draws, and keys to stream it in again\n'
