      '```dart example\n'
      'void main() {\n'
      '  print(\'A long message about terminal cells, 日本語, and keeping every grapheme together on screen.\');\n'
      '}\n'
      '```\n'
      '\n'
      '```\n'
      'unlabelled\n'
      '```\n'
      '\n'
      '```nolanguage\n'
      'unknown label, plain\n'
      '```\n'
      '\n'
      '| Name | Status | Count |\n'
      '|:-----|:------:|------:|\n'
      '| renderer | ready | 2 |\n'
      '| a cell long enough to wrap inside its column | waiting | 10 |\n'
      '\n'
      '---\n'
      '\n'
      '![an image draws nothing](image.png)\n'
      '\n'
      '[ref]: https://ref.example "A definition, shown as written"\n'
      '\'\'\';\n'
      '\n'
      'enum _Tone { dark, light, plain }\n'
      '\n'
      'class _MarkdownExampleState extends State<MarkdownExample> {\n'
      '  final _scroll = ScrollController();\n'
      '  var _tone = _Tone.dark;\n'
      '  var _shown = sample.length;\n'
      '  Timer? _timer;\n'
      '\n'
      '  /// Streams the reply in again, 24 characters every 30 ms.\n'
      '  void _stream() {\n'
      '    _timer?.cancel();\n'
      '    setState(() => _shown = 0);\n'
      '    _timer = Timer.periodic(const Duration(milliseconds: 30), (timer) {\n'
      '      setState(() {\n'
      '        _shown = (_shown + 24).clamp(0, sample.length);\n'
      '        if (_shown == sample.length) timer.cancel();\n'
      '      });\n'
      '    });\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _timer?.cancel();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = switch (_tone) {\n'
      '      _Tone.dark => ThemeData.dark(),\n'
      '      _Tone.light => ThemeData.light(),\n'
      '      _Tone.plain => ThemeData.plain(),\n'
      '    };\n'
      '    return Actions(\n'
      '      bindings: [\n'
      '        Binding(\'ctrl+s\', \'Stream again\', _stream),\n'
      '        Binding(\n'
      '          \'ctrl+t\',\n'
      '          \'Theme\',\n'
      '          () => setState(\n'
      '            () => _tone = _Tone.values[(_tone.index + 1) % _Tone.values.length],\n'
      '          ),\n'
      '        ),\n'
      '        Binding(\'ctrl+q\', \'Quit\', () => exitApp(context)),\n'
      '        ...scrollBindings(\n'
      '          _scroll,\n'
      '          keys: const ScrollKeys(\n'
      '            lineUp: [\'up\', \'shift+up\'],\n'
      '            lineDown: [\'down\', \'shift+down\'],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '      child: Theme(\n'
      '        data: theme,\n'
      '        child: Builder(builder: _content),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _content(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    final text = sample.substring(0, _shown);\n'
      '    final growing = _shown < sample.length;\n'
      '    return Column(\n'
      '      children: [\n'
      '        Text(\n'
      '          \' Markdown  \${_tone.name}, \${_shown * 100 ~/ sample.length}%\',\n'
      '          style: theme.accent,\n'
      '        ),\n'
      '        Expanded(\n'
      '          child: ListView.builder(\n'
      '            controller: _scroll,\n'
      '            itemCount: 1,\n'
      '            itemVersion: (i) => (text, _tone, growing),\n'
      '            itemBuilder: (context, i) => Markdown(text, growing: growing),\n'
      '          ),\n'
      '        ),\n'
      '        const KeyHelp(),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  'picker':
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const PickerExample());\n'
      '\n'
      '/// A searchable picker of thirty choices, some of them two lines tall,\n'
      '/// and what was chosen under it.\n'
      'class PickerExample extends StatefulWidget {\n'
      '  /// The example.\n'
      '  const PickerExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<PickerExample> createState() => _PickerExampleState();\n'
      '}\n'
      '\n'
      'class _PickerExampleState extends State<PickerExample> {\n'
      '  var _chosen = \'nothing yet\';\n'
      '\n'
      '  static final _items = [\n'
      '    for (var i = 1; i <= 30; i++)\n'
      '      PickerItem(\n'
      '        value: \'choice \$i\',\n'
      '        label: i % 7 == 0\n'
      '            ? \'Choice \$i, with a second line\\n  under its label\'\n'
      '            : \'Choice \$i\',\n'
      '      ),\n'
      '  ];\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return Actions(\n'
      '      bindings: [Binding(\'ctrl+q\', \'Quit\', () => exitApp(context))],\n'
      '      // The status and the keys keep their rows; the title and the gaps\n'
      '      // go first where the window is short.\n'
      '      child: LayoutBuilder(\n'
      '        builder: (context, constraints) {\n'
      '          final roomy = constraints.maxHeight >= 10;\n'
      '          return Column(\n'
      '            crossAxisAlignment: CrossAxisAlignment.start,\n'
      '            children: [\n'
      '              if (roomy) ...[\n'
      '                Text(\' Pick one\', style: theme.accent.merge(Style.bold)),\n'
      '                Text(\'\'),\n'
      '              ],\n'
      '              // Bounded by the rows the lines below leave it.\n'
      '              // Keyed: the rows above come and go with the height, and the\n'
      '              // picker must keep its element, and with it its query.\n'
      '              Expanded(\n'
      '                key: const ValueKey(\'picker\'),\n'
      '                child: Align(\n'
      '                  alignment: Alignment.topLeft,\n'
      '                  child: Picker<String>(\n'
      '                    items: _items,\n'
      '                    searchable: true,\n'
      '                    onSelected: (v) => setState(() => _chosen = v),\n'
      '                    onCanceled: () => setState(() => _chosen = \'canceled\'),\n'
      '                    itemExtentVersion: _items,\n'
      '                    itemExtentBuilder: (item, positions, width) =>\n'
      '                        TextLayout.compute(\n'
      '                          TextSpan(item.label),\n'
      '                          maxWidth: width,\n'
      '                        ).height,\n'
      '                    itemBuilder: (_, item, _) => Text(item.label),\n'
      '                  ),\n'
      '                ),\n'
      '              ),\n'
      '              if (roomy) Text(\'\'),\n'
      '              Text(\'Chosen: \$_chosen\', style: theme.dim),\n'
      '              const KeyHelp(),\n'
      '            ],\n'
      '          );\n'
      '        },\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
