  'text_area':
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const TextAreaExample());\n'
      '\n'
      '/// A framed multiline editor: Enter sends what is written above it and\n'
      '/// clears it, shift+enter adds a line, and four rows scroll with the\n'
      '/// cursor, whose line and the rows shown are labelled under the frame.\n'
      'class TextAreaExample extends StatefulWidget {\n'
      '  /// The example.\n'
      '  const TextAreaExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<TextAreaExample> createState() => _TextAreaExampleState();\n'
      '}\n'
      '\n'
      'class _TextAreaExampleState extends State<TextAreaExample> {\n'
      '  final _draft = TextAreaController();\n'
      '  var _sent = \'\';\n'
      '\n'
      '  /// The rows the editor shows at most.\n'
      '  static const _rows = 4;\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _send(String text) {\n'
      '    setState(() => _sent = text);\n'
      '    _draft.clear();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return Actions(\n'
      '      bindings: [Binding(\'ctrl+q\', \'Quit\', () => exitApp(context))],\n'
      '      child: Column(\n'
      '        children: [\n'
      '          Text(\'Text area\', style: theme.accent),\n'
      '          Expanded(\n'
      '            child: Padding(\n'
      '              padding: const EdgeInsets.only(top: 1),\n'
      '              child: Text(_sent),\n'
      '            ),\n'
      '          ),\n'
      '          Padding(\n'
      '            padding: const EdgeInsets.symmetric(horizontal: 1),\n'
      '            child: Box(\n'
      '              border: Border.single,\n'
      '              padding: const EdgeInsets.symmetric(horizontal: 1),\n'
      '              child: TextArea(\n'
      '                controller: _draft,\n'
      '                autofocus: true,\n'
      '                maxHeight: _rows,\n'
      '                placeholder: \'Write a message\',\n'
      '                onSubmit: _send,\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '          ListenableBuilder(\n'
      '            listenable: _draft,\n'
      '            builder: (context) =>\n'
      '                Text(_label(), style: theme.dim, softWrap: false),\n'
      '          ),\n'
      '          Text(\n'
      '            \'Enter sends · Shift+Enter adds a line · Ctrl+Q quits\',\n'
      '            softWrap: false,\n'
      '            overflow: TextOverflow.ellipsis,\n'
      '          ),\n'
      '          const KeyHelp(),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  /// Where the cursor is and which rows show, counted from one, as the\n'
      '  /// editor\'s own scrolling settled them.\n'
      '  String _label() {\n'
      '    final layout = _draft.lastLayout;\n'
      '    if (layout == null) return \'\';\n'
      '    final first = layout.rowOffset + 1;\n'
      '    final last = layout.rowOffset + layout.height;\n'
      '    return \'line \${_draft.cursorLine + 1}, \'\n'
      '        \'column \${_draft.cursorColumn + 1} · \'\n'
      '        \'rows \$first–\$last of \${layout.rows.length}\';\n'
      '  }\n'
      '}\n',
  'diff':
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const DiffExample());\n'
      '\n'
      '/// Diffs of several shapes, with keys to change the theme and scroll: the\n'
      '/// framework\'s `Diff` widget on its own.\n'
      'class DiffExample extends StatefulWidget {\n'
      '  const DiffExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DiffExample> createState() => _DiffExampleState();\n'
      '}\n'
      '\n'
      'const _old = \'\'\'export function greet(name: string): string {\n'
      '  return "hello " + name;\n'
      '}\n'
      '\'\'\';\n'
      '\n'
      'const _new = \'\'\'/** Greets someone by name. */\n'
      'export function greet(name: string): string {\n'
      '  return `hello, \\\${name}`;\n'
      '}\n'
      '\'\'\';\n'
      '\n'
      'final _longOld = [\n'
      '  for (var i = 1; i <= 11; i++) \'step\$i();\',\n'
      '  "  return \'A message about terminal cells, 日本語, and preserving every "\n'
      '      "grapheme while the source line wraps\';",\n'
      '  ...[for (var i = 13; i <= 46; i++) \'more\$i();\'],\n'
      '  \'save();\',\n'
      '  \'\\tindented();\',\n'
      '].join(\'\\n\');\n'
      '\n'
      'final _longNew = _longOld\n'
      '    .replaceFirst(\n'
      '      RegExp(r"  return \'A message[^\\n]*"),\n'
      '      "  return \'A shorter message\';",\n'
      '    )\n'
      '    .replaceFirst(\'\\tindented();\', \'\\tindented(again);\\n\');\n'
      '\n'
      'const _patch = \'\'\'diff --git a/lib/app.dart b/lib/app.dart\n'
      '--- a/lib/app.dart\n'
      '+++ b/lib/app.dart\n'
      '@@ -3,4 +3,4 @@ class App {\n'
      '   /* A comment the hunk opens\n'
      '      and closes. */\n'
      '-  final int count = 1;\n'
      '+  final int count = 2;\n'
      '   final String name;\n'
      '@@ -20,2 +20,3 @@\n'
      '   void run() {}\n'
      '+  void stop() {}\n'
      ' }\n'
      '\'\'\';\n'
      '\n'
      '/// Each sample: a label, and its diff.\n'
      'final samples = <(String, Widget)>[\n'
      '  (\'edit\', const Diff(_old, _new, title: \'src/greeting.ts\')),\n'
      '  (\n'
      '    \'long line, two hunks, a tab\',\n'
      '    Diff(_longOld, _longNew, title: \'src/long.ts\'),\n'
      '  ),\n'
      '  (\'unified patch\', Diff.fromUnified(_patch)),\n'
      '  (\'new file\', const Diff(\'\', \'line one\\n\\nline three\\n\', title: \'notes.md\')),\n'
      '  (\n'
      '    \'unknown language\',\n'
      '    const Diff(\'a\\nb\\n\', \'a\\nc\\n\', title: \'data.nolanguage\'),\n'
      '  ),\n'
      '  (\'equal texts\', const Diff(\'same\\n\', \'same\', title: \'same.txt\')),\n'
      '];\n'
      '\n'
      'enum _Tone { dark, light, untinted, plain }\n'
      '\n'
      'class _DiffExampleState extends State<DiffExample> {\n'
      '  final _scroll = ScrollController();\n'
      '  var _tone = _Tone.dark;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final dark = ThemeData.dark();\n'
      '    final theme = switch (_tone) {\n'
      '      _Tone.dark => dark,\n'
      '      _Tone.light => ThemeData.light(),\n'
      '      _Tone.untinted => dark.copyWith(\n'
      '        diff: DiffTheme(added: dark.diff.added, removed: dark.diff.removed),\n'
      '      ),\n'
      '      _Tone.plain => ThemeData.plain(),\n'
      '    };\n'
      '    return Actions(\n'
      '      bindings: [\n'
      '        Binding(\n'
      '          \'ctrl+t\',\n'
      '          \'Theme\',\n'
      '          () => setState(\n'
      '            () => _tone = _Tone.values[(_tone.index + 1) % _Tone.values.length],\n'
      '          ),\n'
      '        ),\n'
      '        Binding(\'ctrl+q\', \'Quit\', () => exitApp(context)),\n'
      '        ...scrollBindings(\n'
      '          _scroll,\n'
      '          keys: const ScrollKeys(\n'
      '            lineUp: [\'up\', \'shift+up\'],\n'
      '            lineDown: [\'down\', \'shift+down\'],\n'
      '          ),\n'
      '        ),\n'
      '      ],\n'
      '      child: Theme(\n'
      '        data: theme,\n'
      '        child: Builder(builder: _content),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '\n'
      '  Widget _content(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return Column(\n'
      '      children: [\n'
      '        Text(\' Diff  \${_tone.name}\', style: theme.accent),\n'
      '        Expanded(\n'
      '          child: ListView.builder(\n'
      '            controller: _scroll,\n'
      '            itemCount: samples.length,\n'
      '            itemVersion: (i) => _tone,\n'
      '            itemBuilder: (context, i) => Column(\n'
      '              children: [\n'
      '                Text(\'\'),\n'
      '                Text(\' \${samples[i].\$1}\', style: theme.accent),\n'
      '                samples[i].\$2,\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        const KeyHelp(),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n',
  'dialog':
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const DialogExample());\n'
      '\n'
      '/// A dialog anchored above a prompt, as chord asks for a permission: Esc\n'
      '/// or a choice closes it, ctrl+o opens it again.\n'
      'class DialogExample extends StatefulWidget {\n'
      '  /// The example.\n'
      '  const DialogExample({super.key});\n'
      '\n'
      '  @override\n'
      '  State<DialogExample> createState() => _DialogExampleState();\n'
      '}\n'
      '\n'
      'class _DialogExampleState extends State<DialogExample> {\n'
      '  final _link = LayerLink();\n'
      '  late OverlayState _overlay;\n'
      '  OverlayEntry? _entry;\n'
      '  // Entries are not rebuilt with this widget: the page listens itself.\n'
      '  final _answer = ValueNotifier(\'none yet\');\n'
      '  var _first = true;\n'
      '\n'
      '  void _open() {\n'
      '    if (_entry != null) return;\n'
      '    final entry = OverlayEntry(\n'
      '      builder: (_) => CompositedTransformFollower(\n'
      '        link: _link,\n'
      '        followerAnchor: Alignment.bottomLeft,\n'
      '        child: Dialog<String>(\n'
      '          title: Text(\'Allow command?\'),\n'
      '          choices: const [\n'
      '            PickerItem(value: \'allowed once\', label: \'Allow once\'),\n'
      '            PickerItem(value: \'rejected\', label: \'Reject\'),\n'
      '          ],\n'
      '          onSelected: _close,\n'
      '          onCanceled: () => _close(\'closed\'),\n'
      '          child: Text(\n'
      '            \'Run the requested command in this session.\\n\'\n'
      '            \'\\\$ dart analyze\\n\'\n'
      '            \'\\\$ dart format --output=none --set-exit-if-changed .\\n\'\n'
      '            \'\\\$ dart test\',\n'
      '          ),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '    _overlay.insert(entry);\n'
      '    _entry = entry;\n'
      '  }\n'
      '\n'
      '  void _close(String answer) {\n'
      '    final entry = _entry;\n'
      '    if (entry == null) return;\n'
      '    _entry = null;\n'
      '    entry\n'
      '      ..remove()\n'
      '      ..dispose();\n'
      '    _answer.value = answer;\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return Actions(\n'
      '      bindings: [\n'
      '        Binding(\'ctrl+o\', \'Open the dialog\', _open),\n'
      '        Binding(\'ctrl+q\', \'Quit\', () => exitApp(context)),\n'
      '      ],\n'
      '      child: Overlay(\n'
      '        initialEntries: [\n'
      '          OverlayEntry(\n'
      '            builder: (context) {\n'
      '              _overlay = Overlay.of(context);\n'
      '              // Opened on the first frame, once the overlay is laid out.\n'
      '              if (_first) {\n'
      '                _first = false;\n'
      '                context.owner.afterLayout(_open);\n'
      '              }\n'
      '              return Column(\n'
      '                crossAxisAlignment: CrossAxisAlignment.start,\n'
      '                children: [\n'
      '                  Expanded(\n'
      '                    child: ListenableBuilder(\n'
      '                      listenable: _answer,\n'
      '                      builder: (_) => Text(\n'
      '                        \'The transcript is here. Answer: \${_answer.value}\',\n'
      '                        style: theme.dim,\n'
      '                      ),\n'
      '                    ),\n'
      '                  ),\n'
      '                  CompositedTransformTarget(\n'
      '                    link: _link,\n'
      '                    child: const SizedBox(height: 0),\n'
      '                  ),\n'
      '                  Text(\'\'),\n'
      '                  Focus(\n'
      '                    autofocus: true,\n'
      '                    debugLabel: \'prompt\',\n'
      '                    child: Text(\'> /permission\'),\n'
      '                  ),\n'
      '                  const KeyHelp(),\n'
      '                ],\n'
      '              );\n'
      '            },\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  'layers':
      'import \'dart:async\';\n'
      '\n'
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const Layers());\n'
      '\n'
      '/// What ctrl+t picks: the terminal\'s own theme, or one forced over it.\n'
      'enum _ThemeChoice { auto, dark, light, plain }\n'
      '\n'
      '/// A streaming transcript with layers anchored above its prompt: a framed,\n'
      '/// focused picker and frameless, passive completions, over a page that is\n'
      '/// not rebuilt or relaid out by them.\n'
      'class Layers extends StatefulWidget {\n'
      '  /// The fixture; [stream] starts the transcript growing on a timer.\n'
      '  const Layers({super.key, this.stream = true});\n'
      '\n'
      '  /// Whether the transcript grows by itself from the start.\n'
      '  final bool stream;\n'
      '\n'
      '  /// How many times the page itself has been built.\n'
      '  static var pageBuilds = 0;\n'
      '\n'
      '  @override\n'
      '  State<Layers> createState() => LayersState();\n'
      '}\n'
      '\n'
      '/// The fixture\'s state: the transcript, the anchor and the open layers.\n'
      'class LayersState extends State<Layers> {\n'
      '  final transcript = _Transcript();\n'
      '  final scroll = ScrollController(follow: Follow.bottom);\n'
      '  final link = LayerLink();\n'
      '\n'
      '  /// Whether the anchor above the prompt is mounted.\n'
      '  final anchored = ValueNotifier(true);\n'
      '\n'
      '  /// How many rows the prompt takes; more rows move the anchor up.\n'
      '  final promptRows = ValueNotifier(1);\n'
      '\n'
      '  Timer? _timer;\n'
      '  var _choice = _ThemeChoice.auto;\n'
      '  late OverlayState _overlay;\n'
      '  OverlayEntry? _picker, _completions;\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    for (var i = 1; i <= 60; i++) {\n'
      '      transcript.add(\n'
      '        \'line \$i of the transcript, \${\'scrolled back \' * (i % 4)}\',\n'
      '      );\n'
      '    }\n'
      '    if (widget.stream) _toggleStream();\n'
      '  }\n'
      '\n'
      '  void _toggleStream() => setState(() {\n'
      '    if (_timer != null) {\n'
      '      _timer!.cancel();\n'
      '      _timer = null;\n'
      '    } else {\n'
      '      _timer = Timer.periodic(\n'
      '        const Duration(milliseconds: 300),\n'
      '        (_) => transcript.stream(),\n'
      '      );\n'
      '    }\n'
      '  });\n'
      '\n'
      '  /// Opens the picker, [tall] with more rows than fit; closes it when open.\n'
      '  void togglePicker({bool tall = false}) {\n'
      '    if (_closePicker()) return;\n'
      '    final entry = OverlayEntry(\n'
      '      builder: (_) => CompositedTransformFollower(\n'
      '        link: link,\n'
      '        followerAnchor: Alignment.bottomLeft,\n'
      '        child: _Picker(\n'
      '          tall: tall,\n'
      '          onChosen: (choice) {\n'
      '            transcript.add(\'chose \$choice\');\n'
      '            _closePicker();\n'
      '          },\n'
      '          onClosed: _closePicker,\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '    _overlay.insert(entry);\n'
      '    _picker = entry;\n'
      '  }\n'
      '\n'
      '  bool _closePicker() {\n'
      '    final entry = _picker;\n'
      '    if (entry == null) return false;\n'
      '    _picker = null;\n'
      '    entry\n'
      '      ..remove()\n'
      '      ..dispose();\n'
      '    return true;\n'
      '  }\n'
      '\n'
      '  /// Opens the completions, which leave focus on the prompt; closes them.\n'
      '  void toggleCompletions() {\n'
      '    final open = _completions;\n'
      '    if (open != null) {\n'
      '      _completions = null;\n'
      '      open\n'
      '        ..remove()\n'
      '        ..dispose();\n'
      '      return;\n'
      '    }\n'
      '    final entry = OverlayEntry(\n'
      '      requestFocus: false,\n'
      '      builder: (_) => CompositedTransformFollower(\n'
      '        link: link,\n'
      '        followerAnchor: Alignment.bottomLeft,\n'
      '        child: const _Completions(),\n'
      '      ),\n'
      '    );\n'
      '    _overlay.insert(entry);\n'
      '    _completions = entry;\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _timer?.cancel();\n'
      '    transcript.dispose();\n'
      '    scroll.dispose();\n'
      '    anchored.dispose();\n'
      '    promptRows.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  ThemeData? _forced(BuildContext context) {\n'
      '    final brightness = Theme.backgroundOf(context).brightness;\n'
      '    return switch (_choice) {\n'
      '      _ThemeChoice.auto => null,\n'
      '      _ when Theme.noColorOf(context) => ThemeData.plain(\n'
      '        brightness: brightness,\n'
      '      ),\n'
      '      _ThemeChoice.dark => ThemeData.dark(),\n'
      '      _ThemeChoice.light => ThemeData.light(),\n'
      '      _ThemeChoice.plain => ThemeData.plain(brightness: brightness),\n'
      '    };\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final overlay = Overlay(\n'
      '      initialEntries: [\n'
      '        OverlayEntry(\n'
      '          builder: (context) {\n'
      '            _overlay = Overlay.of(context);\n'
      '            return _Page(this);\n'
      '          },\n'
      '        ),\n'
      '      ],\n'
      '    );\n'
      '    final forced = _forced(context);\n'
      '    return Actions(\n'
      '      bindings: [\n'
      '        Binding(\'ctrl+p\', \'Picker\', togglePicker),\n'
      '        Binding(\'ctrl+x p\', \'Tall picker\', () => togglePicker(tall: true)),\n'
      '        Binding(\'ctrl+o\', \'Completions\', toggleCompletions),\n'
      '        Binding(\'ctrl+x a\', \'Anchor\', () => anchored.value = !anchored.value),\n'
      '        Binding(\n'
      '          \'ctrl+x g\',\n'
      '          \'Grow prompt\',\n'
      '          () => promptRows.value = promptRows.value % 4 + 1,\n'
      '        ),\n'
      '        Binding(\'ctrl+s\', \'Stream\', _toggleStream),\n'
      '        Binding(\n'
      '          \'ctrl+t\',\n'
      '          \'Theme\',\n'
      '          () => setState(\n'
      '            () => _choice = _ThemeChoice\n'
      '                .values[(_choice.index + 1) % _ThemeChoice.values.length],\n'
      '          ),\n'
      '        ),\n'
      '        Binding(\'ctrl+q\', \'Quit\', () => exitApp(context)),\n'
      '        ...scrollBindings(scroll),\n'
      '      ],\n'
      '      // Above the overlay, so the layers inherit it; always the same\n'
      '      // wrapper, so a theme change keeps the overlay and its open layers.\n'
      '      child: Theme(data: forced ?? Theme.of(context), child: overlay),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// Lines that a stream appends to and extends.\n'
      'class _Transcript extends ChangeNotifier {\n'
      '  final List<String> lines = [];\n'
      '  var _words = 0;\n'
      '\n'
      '  void add(String line) {\n'
      '    lines.add(line);\n'
      '    _words = 0;\n'
      '    notifyListeners();\n'
      '  }\n'
      '\n'
      '  void stream() {\n'
      '    if (_words == 0 || _words >= 12) {\n'
      '      lines.add(\'streamed\');\n'
      '      _words = 1;\n'
      '    } else {\n'
      '      lines[lines.length - 1] += \' word\${lines.length}\';\n'
      '      _words++;\n'
      '    }\n'
      '    notifyListeners();\n'
      '  }\n'
      '}\n'
      '\n'
      'class _Page extends StatelessWidget {\n'
      '  const _Page(this.app);\n'
      '\n'
      '  final LayersState app;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    Layers.pageBuilds++;\n'
      '    final theme = Theme.of(context);\n'
      '    return Column(\n'
      '      children: [\n'
      '        Expanded(\n'
      '          child: ListenableBuilder(\n'
      '            listenable: app.transcript,\n'
      '            builder: (_) => ListView.builder(\n'
      '              controller: app.scroll,\n'
      '              itemCount: app.transcript.lines.length,\n'
      '              itemVersion: (i) => app.transcript.lines[i],\n'
      '              itemBuilder: (_, i) => Text(app.transcript.lines[i]),\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        ListenableBuilder(\n'
      '          listenable: app.anchored,\n'
      '          builder: (_) => app.anchored.value\n'
      '              ? CompositedTransformTarget(\n'
      '                  link: app.link,\n'
      '                  child: const SizedBox(height: 0),\n'
      '                )\n'
      '              : const SizedBox(),\n'
      '        ),\n'
      '        Text(\'\'),\n'
      '        ListenableBuilder(\n'
      '          listenable: app.promptRows,\n'
      '          builder: (_) => Focus(\n'
      '            autofocus: true,\n'
      '            debugLabel: \'prompt\',\n'
      '            child: Column(\n'
      '              children: [\n'
      '                for (var i = 0; i < app.promptRows.value; i++)\n'
      '                  Text(\n'
      '                    i == 0 ? \'> /model\' : \'  more prompt\',\n'
      '                    style: theme.text,\n'
      '                  ),\n'
      '              ],\n'
      '            ),\n'
      '          ),\n'
      '        ),\n'
      '        _Status(app),\n'
      '        const KeyHelp(),\n'
      '      ],\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// The page\'s own numbers, which the layers must not change.\n'
      'class _Status extends StatefulWidget {\n'
      '  const _Status(this.app);\n'
      '\n'
      '  final LayersState app;\n'
      '\n'
      '  @override\n'
      '  State<_Status> createState() => _StatusState();\n'
      '}\n'
      '\n'
      'class _StatusState extends State<_Status> {\n'
      '  void _changed() => setState(() {});\n'
      '\n'
      '  @override\n'
      '  void initState() {\n'
      '    super.initState();\n'
      '    widget.app.transcript.addListener(_changed);\n'
      '    widget.app.scroll.addListener(_changed);\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    widget.app.transcript.removeListener(_changed);\n'
      '    widget.app.scroll.removeListener(_changed);\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final s = widget.app.scroll;\n'
      '    return Text(\n'
      '      \'page builds \${Layers.pageBuilds} · rows \${s.contentRows} · \'\n'
      '      \'offset \${s.offset} · \${s.isFollowing ? \'following\' : \'scrolled back\'}\',\n'
      '      style: Theme.of(context).dim,\n'
      '      softWrap: false,\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      'const _choices = [\'Careful\', \'Balanced\', \'Quick\', \'Thorough\'];\n'
      '\n'
      '/// A framed list of choices; it takes focus, and Esc closes it.\n'
      'class _Picker extends StatelessWidget {\n'
      '  const _Picker({\n'
      '    required this.tall,\n'
      '    required this.onChosen,\n'
      '    required this.onClosed,\n'
      '  });\n'
      '\n'
      '  final bool tall;\n'
      '  final void Function(String choice) onChosen;\n'
      '  final void Function() onClosed;\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    final choices = [\n'
      '      for (var i = 0; i < (tall ? 40 : _choices.length); i++)\n'
      '        tall ? \'Choice \${i + 1}\' : _choices[i],\n'
      '    ];\n'
      '    return Actions(\n'
      '      bindings: [Binding(\'esc\', \'Close\', onClosed)],\n'
      '      child: Box(\n'
      '        border: Border.rounded.withStyle(theme.focus),\n'
      '        title: \'Models\',\n'
      '        padding: const EdgeInsets.symmetric(horizontal: 1),\n'
      '        child: Column(\n'
      '          mainAxisSize: MainAxisSize.min,\n'
      '          crossAxisAlignment: CrossAxisAlignment.start,\n'
      '          children: [\n'
      '            for (final (i, c) in choices.indexed)\n'
      '              _Choice(c, autofocus: i == 0, onChosen: () => onChosen(c)),\n'
      '            Text(\'Esc to close\', style: theme.dim),\n'
      '          ],\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      'class _Choice extends StatefulWidget {\n'
      '  const _Choice(this.label, {required this.autofocus, required this.onChosen});\n'
      '\n'
      '  final String label;\n'
      '  final bool autofocus;\n'
      '  final void Function() onChosen;\n'
      '\n'
      '  @override\n'
      '  State<_Choice> createState() => _ChoiceState();\n'
      '}\n'
      '\n'
      'class _ChoiceState extends State<_Choice> {\n'
      '  late final node = FocusNode(debugLabel: widget.label);\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    node.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return Actions(\n'
      '      bindings: [Binding(\'enter\', \'Choose\', widget.onChosen)],\n'
      '      child: Focus(\n'
      '        focusNode: node,\n'
      '        autofocus: widget.autofocus,\n'
      '        child: ListenableBuilder(\n'
      '          listenable: node,\n'
      '          builder: (_) => node.hasPrimaryFocus\n'
      '              ? Text(\'❯ \${widget.label}\', style: theme.focus.merge(Style.bold))\n'
      '              : Text(\'  \${widget.label}\'),\n'
      '        ),\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n'
      '\n'
      '/// Frameless completions under a dim rule; they take no focus.\n'
      'class _Completions extends StatelessWidget {\n'
      '  const _Completions();\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) {\n'
      '    final theme = Theme.of(context);\n'
      '    return LayoutBuilder(\n'
      '      builder: (_, room) => Column(\n'
      '        mainAxisSize: MainAxisSize.min,\n'
      '        crossAxisAlignment: CrossAxisAlignment.start,\n'
      '        children: [\n'
      '          Text(\'─\' * room.maxWidth, style: theme.dim, softWrap: false),\n'
      '          for (final c in const [\'/clear\', \'/compact\', \'/config\']) Text(\'  \$c\'),\n'
      '        ],\n'
      '      ),\n'
      '    );\n'
      '  }\n'
      '}\n',
  'mouse':
      'import \'package:chord_tui/chord_tui.dart\';\n'
      '\n'
      'void main() => runApp(const MouseExample());\n'
      '\n'
      '/// Typed mouse reports alongside a keyboard-scrolled log and a focused draft.\n'
      'class MouseExample extends StatefulWidget {\n'
      '  /// The public Listener fixture, with keyboard equivalents for log actions.\n'
      '  const MouseExample({super.key});\n'
      '  @override\n'
      '  State<MouseExample> createState() => _MouseState();\n'
      '}\n'
      '\n'
      'class _MouseState extends State<MouseExample> {\n'
      '  final _capture = PointerCaptureController();\n'
      '  final _scroll = ScrollController(initialOffset: 5);\n'
      '  final _draft = TextAreaController(text: \'draft stays here\');\n'
      '  final _lines = [for (var i = 0; i < 100; i++) \'Sample log row \$i\'];\n'
      '  var _reports = 0;\n'
      '  var _last = \'none\';\n'
      '\n'
      '  @override\n'
      '  void dispose() {\n'
      '    _capture.dispose();\n'
      '    _scroll.dispose();\n'
      '    _draft.dispose();\n'
      '    super.dispose();\n'
      '  }\n'
      '\n'
      '  void _record(MouseEvent event) {\n'
      '    final modifiers = [\n'
      '      if (event.shift) \'shift\',\n'
      '      if (event.alt) \'alt\',\n'
      '      if (event.ctrl) \'ctrl\',\n'
      '    ].join(\'+\');\n'
      '    final line =\n'
      '        \'\${event.kind.name} at (\${event.position.x},\${event.position.y}) \'\n'
      '        \'delta (\${event.scrollDelta.x},\${event.scrollDelta.y}) \${event.button.name}\'\n'
      '        \'\${modifiers.isEmpty ? \'\' : \' \$modifiers\'}\';\n'
      '    setState(() {\n'
      '      _reports++;\n'
      '      _last = line;\n'
      '      _lines.add(\'#\$_reports \$line\');\n'
      '    });\n'
      '    if (event.kind == MouseEventKind.wheel) {\n'
      '      for (var i = 0; i < event.scrollDelta.y.abs(); i++) {\n'
      '        event.scrollDelta.y < 0 ? _scroll.lineUp() : _scroll.lineDown();\n'
      '      }\n'
      '    }\n'
      '  }\n'
      '\n'
      '  @override\n'
      '  Widget build(BuildContext context) => Listener(\n'
      '    behavior: HitTestBehavior.opaque,\n'
      '    captureController: _capture,\n'
      '    onPointerDown: (event) {\n'
      '      if (event.button == MouseButton.primary) _capture.capture();\n'
      '      _record(event);\n'
      '    },\n'
      '    onPointerMove: _record,\n'
      '    onPointerCancel: _record,\n'
      '    onPointerUp: _record,\n'
      '    onPointerSignal: _record,\n'
      '    child: Actions(\n'
      '      bindings: [\n'
      '        ...scrollBindings(\n'
      '          _scroll,\n'
      '          keys: const ScrollKeys(\n'
      '            lineUp: [\'shift+up\'],\n'
      '            lineDown: [\'shift+down\'],\n'
      '          ),\n'
      '        ),\n'
      '        Binding(\'ctrl+l\', \'Clear event log\', () {\n'
      '          setState(() {\n'
      '            _lines.clear();\n'
      '            _reports = 0;\n'
      '            _last = \'none\';\n'
      '          });\n'
      '          _scroll.toTop();\n'
      '        }),\n'
      '        Binding(\'ctrl+q\', \'Quit\', () => exitApp(context)),\n'
      '      ],\n'
      '      child: Column(\n'
      '        crossAxisAlignment: CrossAxisAlignment.start,\n'
      '        children: [\n'
      '          Text(\n'
      '            \'Pointer events · reports: \$_reports\',\n'
      '            style: Theme.of(context).accent,\n'
      '          ),\n'
      '          Text(\'Last event: \$_last\'),\n'
      '          Expanded(\n'
      '            child: ListView.builder(\n'
      '              controller: _scroll,\n'
      '              itemCount: _lines.length,\n'
      '              itemVersion: (i) => _lines[i],\n'
      '              itemBuilder: (_, i) => Text(_lines[i]),\n'
      '            ),\n'
      '          ),\n'
      '          SizedBox(\n'
      '            height: 5,\n'
      '            child: Box(\n'
      '              border: Border.single,\n'
      '              padding: const EdgeInsets.symmetric(horizontal: 1),\n'
      '              child: TextArea(\n'
      '                controller: _draft,\n'
      '                autofocus: true,\n'
      '                maxHeight: 3,\n'
      '              ),\n'
      '            ),\n'
      '          ),\n'
      '          KeyHelp.builder(\n'
      '            builder: (context, bindings, pending) => Text(\n'
      '              [\n'
      '                for (final binding in bindings)\n'
      '                  if (const {\n'
      '                    \'shift+up\',\n'
      '                    \'shift+down\',\n'
      '                    \'pageup\',\n'
      '                    \'pagedown\',\n'
      '                    \'home\',\n'
      '                    \'end\',\n'
      '                    \'ctrl+l\',\n'
      '                    \'ctrl+q\',\n'
      '                    \'super+left\',\n'
      '                    \'super+right\',\n'
      '                  }.contains(\'\${binding.chord}\'))\n'
      '                    \'\${binding.chord} \${binding.description}\',\n'
      '              ].join(\' · \'),\n'
      '              style: Theme.of(context).dim,\n'
      '            ),\n'
      '          ),\n'
      '        ],\n'
      '      ),\n'
      '    ),\n'
      '  );\n'
      '}\n',
};

/// README's testing example, as its Testing section has it.
const testingSource =
    'import \'package:chord_tui/chord_tui.dart\';\n'
    'import \'package:chord_tui/testing.dart\';\n'
    'import \'package:test/test.dart\';\n'
    '\n'
    'void main() {\n'
    '  testWidgets(\'Esc cancels a dialog\', (tester) async {\n'
    '    var canceled = false;\n'
    '    await tester.pumpWidget(\n'
    '      Dialog<void>(\n'
    '        title: Text(\'Notice\'),\n'
    '        onCanceled: () => canceled = true,\n'
    '        child: Text(\'Checks passed\'),\n'
    '      ),\n'
    '      size: Size(80, 24),\n'
    '    );\n'
    '    expect(tester.screen, shows(\'Checks passed\'));\n'
    '    await tester.press(\'esc\');\n'
    '    expect(canceled, isTrue);\n'
    '  });\n'
    '}\n';
